preConditionHook:
// DOW'S UPTREND, THE STRUCTURAL TREND TEST: the most recent confirmed swing
// high is ABOVE the one before it AND the most recent confirmed swing low is
// ABOVE the one before it. Grimes's markup phase (G02-02) and his Dow-theory
// uptrend (G03-26) are the same bars, so they are one rule. Short is the
// mirror: lower highs and lower lows, the markdown phase.
//
// NOT a placement of HigherSwingLow. That rule tests ONE series per side --
// higher lows on the long, lower highs on the short -- and neither a placement
// of it nor its per-placement negation asks for BOTH series on the SAME side,
// which is the whole content of Dow's definition. Merge decision 15 names this
// rule the pivot alternative to EmaSlope, not the default trend test.
//
// numLegsToConfirm is not an input: the pivot count is fixed at two per series
// by merge decision 14's newest-first scan, and the run form is already
// HigherSwingLowRun's `legs` input.
//
// THE PIVOT SCAN IS INLINED, mirroring the twin's SwingHigh / SwingHighBar /
// SwingLow / SwingLowBar at Occurrence 1 and 2 -- rules in this corpus never
// reference each other. MEASURED (EL_Swing_Probe.txt / el_swing_output1.txt,
// @ES 60 min): the pivot test is MIXED -- AT OR BEYOND the `strength` OLDER
// bars, STRICTLY BEYOND the `strength` NEWER bars, and bars-ago indexing makes
// the SMALLER index the NEWER bar, so the strict half is the k < j loop; the
// confirmation lag is exactly `strength` bars, never 0 or 1, so j starts there
// and the read is lookahead-safe; maxBarsBack is EL's Length with candidate
// offsets 0..maxBarsBack-1 inclusive while the neighbourhood test reaches
// `strength` bars PAST the window, so the deepest index touched is
// maxBarsBack - 1 + strength; an empty window is the -1 SENTINEL, guarded here
// on the BAR INDEX and never on a price -- a back-adjusted series can print
// -1.00 as a real price. The comparisons carry the 2.22e-12 relational
// tolerance. Occurrence 3+ is UNMEASURED and never asked for. The low side's
// tie sense is the mirror of the measured high-side rule. No WFSafe_SwingLow
// exists, so plain EL governs.
//
// Written WITHOUT break and with the < 2 counters, statement for statement with
// the twin's Occurrence 1 / 2 reads.
//
// Every scratch value that must survive the bar is a localVariables entry
// rather than a hook-scope declaration, so the hooks survive a double
// placement; the loop counters and per-candidate flags are block-scoped.
//
// Deepest bar touched: maxBarsBack - 1 + strength.
pivS = (int)strength;
pivW = (int)maxBarsBack;
nHi = 0;
nLo = 0;
hiPx1 = -1.0;
hiBar1 = -1.0;
hiPx2 = -1.0;
hiBar2 = -1.0;
loPx1 = -1.0;
loBar1 = -1.0;
loPx2 = -1.0;
loBar2 = -1.0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivS; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    if (okHi && nHi < 2) {
        nHi = nHi + 1;
        if (nHi == 1) { hiPx1 = high[j]; hiBar1 = (double)j; }
        if (nHi == 2) { hiPx2 = high[j]; hiBar2 = (double)j; }
    }
    if (okLo && nLo < 2) {
        nLo = nLo + 1;
        if (nLo == 1) { loPx1 = low[j]; loBar1 = (double)j; }
        if (nLo == 2) { loPx2 = low[j]; loBar2 = (double)j; }
    }
}
haveAll = (hiBar1 != -1.0) && (hiBar2 != -1.0) && (loBar1 != -1.0) && (loBar2 != -1.0);
